import { access } from 'node:fs/promises';
import { delimiter, join } from 'node:path';
import { detectHostProfile } from './host.mjs';

async function defaultResolver(binary) {
  const path = process.env.PATH ?? '';
  const suffixes = process.platform === 'win32' ? ['', '.exe', '.cmd', '.bat'] : [''];
  for (const dir of path.split(delimiter).filter(Boolean)) {
    for (const suffix of suffixes) {
      const candidate = join(dir, `${binary}${suffix}`);
      try {
        await access(candidate);
        return candidate;
      } catch {}
    }
  }
  return null;
}

function cap(id, category, provider, path, operations, sideEffectClass = 'R') {
  return {
    id,
    category,
    provider,
    status: path ? 'AVAILABLE' : 'UNAVAILABLE',
    path,
    operations,
    side_effect_class: sideEffectClass
  };
}

export async function discoverCapabilities({ resolver = defaultResolver, host = detectHostProfile() } = {}) {
  const binaries = ['git', 'gh', 'glab', 'docker', 'podman', 'adb', 'emulator', 'gradle', 'java', 'npm', 'pnpm', 'yarn', 'pytest', 'cargo', 'go'];
  const entries = Object.fromEntries(await Promise.all(binaries.map(async (name) => [name, await resolver(name)])));
  const containerPath = entries.docker ?? entries.podman;
  const ciPath = entries.gh ?? entries.glab;
  const buildPath = entries.gradle ?? entries.npm ?? entries.pnpm ?? entries.yarn ?? entries.cargo ?? entries.go;
  const verifierPath = entries.pytest ?? entries.gradle ?? entries.npm ?? entries.cargo ?? entries.go;

  return [
    cap('terminal.local', 'terminal', 'local-process', process.execPath, ['run'], 'L'),
    cap('repo.git', 'repository', 'git', entries.git, ['inspect', 'diff', 'worktree'], 'L'),
    cap('ci.hosting', 'ci', entries.gh ? 'github' : entries.glab ? 'gitlab' : null, ciPath, ['list', 'view', 'trigger'], 'E'),
    cap(entries.docker ? 'container.docker' : entries.podman ? 'container.podman' : 'container.local', 'container', entries.docker ? 'docker' : entries.podman ? 'podman' : null, containerPath, ['run'], 'L'),
    cap('build.local', 'build', buildPath ? 'project-toolchain' : null, buildPath, ['run'], 'L'),
    cap('sandbox.worktree', 'sandbox', 'git-worktree', entries.git, ['create-detached'], 'L'),
    cap('device.android', 'device', 'adb', entries.adb, ['list', 'shell', 'install', 'logcat'], 'L'),
    cap('emulator.android', 'device', 'android-emulator', entries.emulator, ['list-avds', 'start'], 'L'),
    cap('verifier.local', 'verifier', 'project-toolchain', verifierPath, ['run-suite'], 'L'),
    cap('communications.voice-concierge', 'communications', 'omega-internal', process.execPath, ['persona-route','channel-route','conversation-plan','appointment-handoff','post-call-evidence','opt-out-gate'], 'E'),
    {
      id: 'knowledge.phone-folder',
      category: 'knowledge',
      provider: 'android-filesystem-readonly',
      status: process.env.OMEGA_KNOWLEDGE_ROOT ? 'AVAILABLE' : 'UNAVAILABLE',
      path: null,
      operations: ['info', 'list', 'metadata', 'read', 'search'],
      side_effect_class: 'R'
    },
    {
      id: host.termux ? 'runtime.termux' : host.cloudRun ? 'runtime.cloud-run' : host.android ? 'runtime.android' : 'runtime.host',
      category: 'runtime',
      provider: host.termux ? 'termux' : host.cloudRun ? 'google-cloud-run' : host.android ? 'android' : host.platform,
      status: 'AVAILABLE',
      path: host.prefix ?? host.home ?? host.cwd,
      operations: ['host-info'],
      side_effect_class: 'R'
    },
    {
      id: 'mcp.remote-http',
      category: 'mcp',
      provider: 'streamable-http',
      status: host.remoteMcp ? 'AVAILABLE' : 'UNAVAILABLE',
      path: host.remoteMcp ? '/mcp' : null,
      operations: ['tools/list', 'tools/call', 'oauth-protected-resource'],
      side_effect_class: 'R'
    }
  ];
}

import { resolve } from 'node:path';
import { Policy } from './policy.mjs';
import { runProcess } from './process.mjs';
import { discoverCapabilities } from './capabilities.mjs';
import { inspectArtifact } from './artifact.mjs';
import { inspectRepository, createDetachedWorktree } from '../adapters/git.mjs';
import { buildCiCommand } from '../adapters/ci.mjs';
import { buildContainerRun } from '../adapters/container.mjs';
import { buildAdbCommand, buildEmulatorCommand } from '../adapters/android.mjs';
import { detectHostProfile } from './host.mjs';
import { VoiceConciergeRuntime } from '../communications/voice-concierge.mjs';
import { PhoneKnowledgeRoot } from '../knowledge/phone-knowledge-root.mjs';

function parseRoots(value) {
  if (!value) return [process.cwd()];
  return value.split(process.platform === 'win32' ? ';' : ':').filter(Boolean).map((v) => resolve(v));
}

export class OmegaControlPlane {
  constructor({ workspaceRoots = parseRoots(process.env.OMEGA_WORKSPACE_ROOTS), policy, knowledgeRoot = process.env.OMEGA_KNOWLEDGE_ROOT, knowledgeRuntime } = {}) {
    this.workspaceRoots = workspaceRoots.map((root) => resolve(root));
    this.policy = policy ?? new Policy({ workspaceRoots: this.workspaceRoots });
    this.voiceConciergeRuntime = new VoiceConciergeRuntime();
    this.knowledgeRuntime = knowledgeRuntime ?? (knowledgeRoot ? new PhoneKnowledgeRoot({ root: knowledgeRoot }) : null);
  }

  capabilities() {
    return discoverCapabilities();
  }

  hostInfo() {
    return { ...detectHostProfile(), workspaceRoots: [...this.workspaceRoots], knowledgeRootConfigured: Boolean(this.knowledgeRuntime) };
  }

  terminalRun(input) {
    return runProcess({ ...input, source: 'terminal', policy: this.policy });
  }

  repositoryInspect(cwd) {
    return inspectRepository({ cwd, policy: this.policy });
  }

  sandboxCreate({ repository, destination, revision }) {
    return createDetachedWorktree({ repository, destination, revision, policy: this.policy });
  }

  async ci({ cwd, provider, action, limit, runId, workflow, ref }) {
    const argv = buildCiCommand({ provider, action, limit, runId, workflow, ref });
    const sideEffect = action === 'trigger' ? 'E' : 'R';
    return await runProcess({ argv, cwd, sideEffect, source: 'internal', policy: this.policy, timeoutMs: 120_000 });
  }

  async containerRun(input) {
    const plan = buildContainerRun(input);
    return await runProcess({ ...plan, source: 'project', policy: this.policy, timeoutMs: input.timeoutMs ?? 300_000, maxOutputBytes: input.maxOutputBytes ?? 2_097_152 });
  }

  async buildRun({ cwd, argv, timeoutMs = 600_000, maxOutputBytes = 4_194_304 }) {
    return await runProcess({ argv, cwd, sideEffect: 'L', source: 'project', policy: this.policy, timeoutMs, maxOutputBytes });
  }

  async verify({ cwd, checks, timeoutMs = 600_000 }) {
    if (!Array.isArray(checks) || checks.length === 0 || checks.length > 20) throw new Error('checks must contain between 1 and 20 commands');
    const results = [];
    for (const check of checks) {
      if (!Array.isArray(check.argv) || check.argv.length === 0) throw new Error('Each verification check requires argv');
      const result = await runProcess({ argv: check.argv, cwd, sideEffect: 'L', source: 'project', policy: this.policy, timeoutMs: check.timeoutMs ?? timeoutMs, maxOutputBytes: 2_097_152 });
      results.push({ name: check.name ?? check.argv.join(' '), ...result });
      if (result.exitCode !== 0) break;
    }
    return { passed: results.length === checks.length && results.every((item) => item.exitCode === 0), results };
  }

  async device({ cwd, kind = 'adb', ...input }) {
    if (kind === 'adb' && input.action === 'install') input.artifact = this.policy.assertPath(input.artifact);
    const argv = kind === 'emulator' ? buildEmulatorCommand(input) : buildAdbCommand(input);
    const mutationActions = new Set(['shell', 'install', 'start']);
    const sideEffect = mutationActions.has(input.action) ? 'L' : 'R';
    return await runProcess({ argv, cwd, sideEffect, source: mutationActions.has(input.action) ? 'project' : 'internal', policy: this.policy, timeoutMs: 180_000 });
  }

  voiceConcierge(input = {}) {
    return this.voiceConciergeRuntime.action(input);
  }

  #knowledge() {
    if (!this.knowledgeRuntime) {
      const error = new Error('Phone knowledge root is not configured');
      error.code = 'KNOWLEDGE_ROOT_NOT_CONFIGURED';
      throw error;
    }
    return this.knowledgeRuntime;
  }

  knowledgeInfo() { return this.#knowledge().info(); }
  knowledgeList(input = {}) { return this.#knowledge().list(input); }
  knowledgeRead(input) { return this.#knowledge().read(input); }
  knowledgeSearch(input) { return this.#knowledge().search(input); }
  knowledgeMetadata(input) { return this.#knowledge().metadata(input); }

  artifactInspect(path) {
    return inspectArtifact({ path, workspaceRoots: this.workspaceRoots });
  }
}

import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { basename, extname, isAbsolute, relative, resolve, sep } from 'node:path';
import { lstat, open, readdir, realpath, stat } from 'node:fs/promises';

const execFileAsync = promisify(execFile);
const TEXT_EXTENSIONS = new Set([
  '.txt', '.md', '.markdown', '.json', '.jsonl', '.csv', '.tsv',
  '.html', '.htm', '.xml', '.yaml', '.yml', '.ini', '.toml', '.log',
  '.js', '.mjs', '.cjs', '.ts', '.tsx', '.jsx', '.py', '.java', '.kt',
  '.kts', '.c', '.h', '.cpp', '.hpp', '.rs', '.go', '.sh', '.sql'
]);
const ARCHIVE_TEXT_EXTENSIONS = new Set(['.docx', '.odt']);
const SUPPORTED_EXTENSIONS = new Set([...TEXT_EXTENSIONS, ...ARCHIVE_TEXT_EXTENSIONS, '.pdf']);

function inside(root, candidate) {
  return candidate === root || candidate.startsWith(`${root}${sep}`);
}

function publicPath(root, absolute) {
  const value = relative(root, absolute);
  return value.split(sep).join('/');
}

function decodeEntities(value) {
  return value
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function stripMarkup(value) {
  return decodeEntities(
    value
      .replace(/<script[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style[\s\S]*?<\/style>/gi, ' ')
      .replace(/<[^>]+>/g, ' ')
      .replace(/\s+/g, ' ')
  ).trim();
}

async function defaultCommandRunner({ argv, timeoutMs = 120_000, maxOutputBytes = 4_194_304 }) {
  const [command, ...args] = argv;
  try {
    const result = await execFileAsync(command, args, {
      timeout: timeoutMs,
      maxBuffer: Math.max(maxOutputBytes * 2, 1_048_576),
      encoding: 'utf8',
      windowsHide: true
    });
    return { exitCode: 0, stdout: result.stdout ?? '', stderr: result.stderr ?? '' };
  } catch (error) {
    if (error?.code === 'ENOENT') {
      const unavailable = new Error(`Required read-only extractor is unavailable: ${command}`);
      unavailable.code = 'EXTRACTOR_UNAVAILABLE';
      throw unavailable;
    }
    const failure = new Error(error?.stderr || error?.message || String(error));
    failure.code = 'EXTRACTION_FAILED';
    throw failure;
  }
}

export class PhoneKnowledgeRoot {
  constructor({ root, commandRunner = defaultCommandRunner } = {}) {
    if (!root) throw new Error('Phone knowledge root is not configured');
    this.root = resolve(root);
    this.commandRunner = commandRunner;
    this._canonicalRoot = null;
  }

  async #canonicalRootPath() {
    if (!this._canonicalRoot) this._canonicalRoot = await realpath(this.root);
    return this._canonicalRoot;
  }

  async #resolve(relativePath = '') {
    const root = await this.#canonicalRootPath();
    if (isAbsolute(relativePath)) throw new Error('Path is outside knowledge root');
    const lexical = resolve(root, relativePath || '.');
    if (!inside(root, lexical)) throw new Error('Path is outside knowledge root');
    const canonical = await realpath(lexical);
    if (!inside(root, canonical)) throw new Error('Path is outside knowledge root');
    return { root, canonical };
  }

  async info() {
    const root = await this.#canonicalRootPath();
    const info = await stat(root);
    if (!info.isDirectory()) throw new Error('Configured knowledge root is not a directory');
    return {
      configured: true,
      available: true,
      rootName: basename(root),
      mode: 'read-only',
      supportedExtensions: [...SUPPORTED_EXTENSIONS].sort()
    };
  }

  async metadata({ path }) {
    const { root, canonical } = await this.#resolve(path);
    const info = await stat(canonical);
    return {
      path: publicPath(root, canonical),
      type: info.isDirectory() ? 'directory' : info.isFile() ? 'file' : 'other',
      size: info.size,
      modifiedAt: info.mtime.toISOString(),
      extension: info.isFile() ? extname(canonical).toLowerCase() : ''
    };
  }

  async list({ path = '', recursive = false, maxEntries = 1000 } = {}) {
    const { root, canonical } = await this.#resolve(path);
    const baseInfo = await stat(canonical);
    if (!baseInfo.isDirectory()) throw new Error('Knowledge list path is not a directory');
    const entries = [];
    const queue = [canonical];

    while (queue.length && entries.length < maxEntries) {
      const current = queue.shift();
      const children = await readdir(current, { withFileTypes: true });
      children.sort((a, b) => a.name.localeCompare(b.name));

      for (const child of children) {
        if (entries.length >= maxEntries) break;
        const absolute = resolve(current, child.name);
        const linkInfo = await lstat(absolute);
        if (linkInfo.isSymbolicLink()) {
          let blocked = false;
          try {
            const target = await realpath(absolute);
            blocked = !inside(root, target);
          } catch {
            blocked = true;
          }
          entries.push({
            path: publicPath(root, absolute),
            type: 'symlink',
            blocked,
            size: linkInfo.size,
            modifiedAt: linkInfo.mtime.toISOString(),
            extension: extname(child.name).toLowerCase()
          });
          continue;
        }

        const info = await stat(absolute);
        const type = info.isDirectory() ? 'directory' : info.isFile() ? 'file' : 'other';
        entries.push({
          path: publicPath(root, absolute),
          type,
          size: info.size,
          modifiedAt: info.mtime.toISOString(),
          extension: info.isFile() ? extname(child.name).toLowerCase() : ''
        });
        if (recursive && info.isDirectory()) queue.push(absolute);
      }

      if (!recursive) break;
    }

    return {
      rootName: basename(root),
      path: publicPath(root, canonical),
      recursive,
      maxEntries,
      truncated: entries.length >= maxEntries && queue.length > 0,
      entries
    };
  }

  async #readBoundedFile(path, maxBytes) {
    const handle = await open(path, 'r');
    try {
      const buffer = Buffer.alloc(maxBytes + 1);
      const { bytesRead } = await handle.read(buffer, 0, buffer.length, 0);
      return {
        buffer: buffer.subarray(0, Math.min(bytesRead, maxBytes)),
        truncated: bytesRead > maxBytes
      };
    } finally {
      await handle.close();
    }
  }

  async read({ path, maxBytes = 1_048_576 }) {
    const { root, canonical } = await this.#resolve(path);
    const info = await stat(canonical);
    if (!info.isFile()) throw new Error('Knowledge read path is not a regular file');
    const extension = extname(canonical).toLowerCase();
    if (!SUPPORTED_EXTENSIONS.has(extension)) {
      const error = new Error(`Unsupported knowledge file type: ${extension || '(none)'}`);
      error.code = 'UNSUPPORTED_FILE_TYPE';
      throw error;
    }

    let text = '';
    let truncated = false;
    let extractor = 'utf8';

    if (extension === '.pdf') {
      const result = await this.commandRunner({
        argv: ['pdftotext', '-layout', canonical, '-'],
        timeoutMs: 180_000,
        maxOutputBytes: Math.max(maxBytes, 1_048_576)
      });
      text = String(result.stdout ?? '');
      extractor = 'pdftotext';
      if (Buffer.byteLength(text, 'utf8') > maxBytes) {
        text = Buffer.from(text, 'utf8').subarray(0, maxBytes).toString('utf8');
        truncated = true;
      }
    } else if (ARCHIVE_TEXT_EXTENSIONS.has(extension)) {
      const member = extension === '.docx' ? 'word/document.xml' : 'content.xml';
      const result = await this.commandRunner({
        argv: ['unzip', '-p', canonical, member],
        timeoutMs: 120_000,
        maxOutputBytes: Math.max(maxBytes, 1_048_576)
      });
      text = stripMarkup(String(result.stdout ?? ''));
      extractor = extension === '.docx' ? 'docx-xml' : 'odt-xml';
      if (Buffer.byteLength(text, 'utf8') > maxBytes) {
        text = Buffer.from(text, 'utf8').subarray(0, maxBytes).toString('utf8');
        truncated = true;
      }
    } else {
      const bounded = await this.#readBoundedFile(canonical, maxBytes);
      text = bounded.buffer.toString('utf8');
      truncated = bounded.truncated;
      if (extension === '.html' || extension === '.htm' || extension === '.xml') {
        text = stripMarkup(text);
        extractor = 'markup-text';
      }
    }

    return {
      path: publicPath(root, canonical),
      extension,
      size: info.size,
      modifiedAt: info.mtime.toISOString(),
      extractor,
      truncated,
      text
    };
  }

  async search({
    query,
    path = '',
    recursive = true,
    maxFiles = 250,
    maxMatches = 100,
    maxBytesPerFile = 262_144
  }) {
    if (!query?.trim()) throw new Error('Search query is required');
    const listing = await this.list({
      path,
      recursive,
      maxEntries: Math.min(Math.max(maxFiles * 8, maxFiles), 20_000)
    });
    const candidates = listing.entries
      .filter((entry) => entry.type === 'file' && SUPPORTED_EXTENSIONS.has(entry.extension))
      .slice(0, maxFiles);
    const needle = query.toLocaleLowerCase();
    const matches = [];
    const errors = [];

    for (const entry of candidates) {
      if (matches.length >= maxMatches) break;
      try {
        const doc = await this.read({ path: entry.path, maxBytes: maxBytesPerFile });
        const lower = doc.text.toLocaleLowerCase();
        let offset = lower.indexOf(needle);
        while (offset !== -1 && matches.length < maxMatches) {
          const start = Math.max(0, offset - 120);
          const end = Math.min(doc.text.length, offset + query.length + 220);
          matches.push({
            path: entry.path,
            extension: entry.extension,
            offset,
            snippet: doc.text.slice(start, end).replace(/\s+/g, ' ').trim(),
            truncatedSource: doc.truncated
          });
          offset = lower.indexOf(needle, offset + Math.max(needle.length, 1));
        }
      } catch (error) {
        errors.push({ path: entry.path, code: error?.code ?? 'READ_FAILED', message: error?.message ?? String(error) });
      }
    }

    return {
      query,
      scannedFiles: candidates.length,
      matches,
      errors,
      truncated: matches.length >= maxMatches || listing.truncated
    };
  }
}

import { McpServer } from '@modelcontextprotocol/server';
